{
  "summary": "Services are not provided after the contract term, but if Papa John's engages Celebrity's performance or service subject to a union's jurisdiction after the term, Papa John's must pay required union fees and minimum payments.",
  "evidence": [
    {
      "passage_id": 7,
      "quote": "Service Days that are allocated for a particular Contract Year may not be carried into future Contract Years, or beyond the expiration or early termination of the Term"
    },
    {
      "passage_id": 9,
      "quote": "If PAPA JOHN'S engages any performance or service of CELEBRITY hereunder in any way that is subject to the jurisdiction of any applicable union, guild or other organization of which CELEBRITY is a member (including, without limitation, SAG-AFTRA), either during or after the Term, then PAPA JOHN'S shall pay, as required by such union, guild or other organization, all minimum (and other, as applicable) payments or fees (or for SAG-AFTRA, minimum pension and welfare contributions) required to be made with respect to PAPA JOHN'S use of the Services hereunder (\"Union Fee(s)\")."
    }
  ]
}
